/**
 * Space activates focused buttons and belongs in free-text fields. Numeric and
 * expression controls do not require spaces, though, and feature inspectors
 * can leave one focused after the user clicks a face in the viewport; let the
 * face shortcut through in that specific case without touching its value.
 */
/** Freeze the history-edit intent at selection, for both copy and planning. */
function faceOffsetTargetFields(
  document: ProjectDocument | null,
  bodyId: string,
  reference: FaceTopology['reference'],
  faceHash: number
): Pick<FaceTarget, 'extrudeFeatureId' | 'resizeBodyFeatureId'> {
  const extrude = document
    ? extrudeCapAncestor(document, bodyId as BodyId, reference, faceHash)
    : null;
  if (extrude) return { extrudeFeatureId: extrude.feature.featureId };
  const box = document
    ? primitiveBoxFaceAncestor(document, bodyId as BodyId, reference, faceHash)
    : null;
  return box ? { resizeBodyFeatureId: box.primitive.featureId } : {};
}

/** The interaction machine's view of one picked region. */
function regionTargetFor(region: RegionPickData): RegionTarget {
  return {
    sketchId: region.sketchId,
    regionFingerprint: region.regionFingerprint,
    samplePoint: region.samplePoint,
    area: region.area,
    sourceEntityIds: region.sourceEntityIds,
    sourceBoundaryLoops: region.sourceBoundaryLoops
  };
}

function focusedControlOwnsSpace(target: HTMLElement | null): boolean {
  if (!target) {
    return false;
  }
  if (target instanceof HTMLInputElement) {
    return (
      target.type !== 'number' &&
      target.type !== 'range' &&
      !target.closest('.expr-field')
    );
  }
  if (
    target.closest(
      'button, a, [role="button"], [role="tab"], [contenteditable="true"]'
    )
  ) {
    return true;
  }
  if (target.tagName === 'TEXTAREA' || target.tagName === 'SELECT') {
    return true;
  }
  return false;
}

/**
 * The STEP/STL import run, loaded on the gesture that imports a file.
 *
 * It is several kilobytes of orchestration — checksum marks, artifact
 * archival, abort plumbing, the guided Shapr3D path — and a session that
 * never imports a file should not carry it at launch. Both call sites are
 * already inside an async handler that is about to read a file off disk, so
 * the fetch costs nothing measurable next to that. The refusals that come
 * BEFORE it (unsupported extension, a lone `.shapr`) stay synchronous.
 */
const stepImportRun = () => import('./lib/stepImportRun');

